// 卡片答案取自已整理的章节正文，标题精确匹配以避免指向错误内容。
const CARD_TOPICS=[
[1,'地理信息系统（GIS）','信息、地理信息与 GIS'],[1,'GIS 的组成','GIS 的组成'],[2,'大地水准面与参考椭球','地球表面与参考面'],[2,'地图投影','地图投影及变形'],[3,'空间数据模型','概念、逻辑与物理模型'],[3,'对象模型与场模型','对象模型与场模型'],[3,'空间关系','空间关系'],[4,'矢量数据结构','矢量数据结构'],[4,'拓扑关系','拓扑及其作用'],[4,'栅格数据结构','栅格及压缩编码'],[5,'空间数据库','空间数据库'],[5,'空间索引','空间索引与查询'],[6,'空间与属性数据采集','空间与属性数据采集'],[6,'栅格重采样','栅格重采样'],[7,'空间分析','空间分析与空间度量'],[7,'叠置分析','叠置分析'],[7,'缓冲区分析','缓冲区分析'],[7,'网络分析与窗口分析','窗口分析与网络分析'],[8,'数字高程模型（DEM）','DEM 与地形表达'],[8,'地形插值','地形插值'],[8,'坡度、坡向与曲率','坡度、坡向与曲率'],[9,'空间统计分析','空间统计与普通统计'],[9,'空间自相关','空间自相关'],[9,'空间插值与核密度','核密度与空间插值'],[10,'地理信息可视化','地理信息可视化'],[10,'地图符号与注记','符号、注记和图面配置'],[11,'网络 GIS','网络 GIS'],[11,'地理信息网络服务','地理信息网络服务']
];
function cardsData(){return CARD_TOPICS.map(([chapter,term,title])=>{const j=LESSONS[chapter-1].sections.findIndex(s=>s[0]===title);return j<0?null:{chapter,term,title,j,answer:LESSONS[chapter-1].sections[j].slice(1).join(' ')}}).filter(Boolean)}
function flashcards(){return `<div class="fc-head"><span class="fc-eyebrow">RECALL & REVIEW</span><h1 class="page-title">知识卡片</h1><p class="page-lead">先回想概念，再翻面核对；可以按章节浏览或随机抽取。</p></div><div class="fc-toolbar"><label for="fc-chapter">章节</label><select id="fc-chapter"><option value="all">全部章节</option>${titles.map((t,i)=>`<option value="${i+1}">第 ${i+1} 章 · ${esc(t)}</option>`).join('')}</select><button id="fc-browse" type="button">浏览卡片</button><button id="fc-random" type="button">随机抽卡</button></div><p id="fc-status" aria-live="polite"></p><div id="fc-content"></div><p class="fc-note">卡片根据网站已整理的教材内容生成，帮助主动回忆；完整定义与出处请进入对应章节核对。</p>`}
function initFlashcards(){const all=cardsData(),select=document.querySelector('#fc-chapter'),content=document.querySelector('#fc-content'),status=document.querySelector('#fc-status');let mode='browse',previous=null;function pool(){return all.filter(x=>select.value==='all'||x.chapter===Number(select.value))}function card(c){return `<article class="fc-card"><button class="fc-flip" type="button" aria-expanded="false"><span class="fc-front"><span class="fc-meta">第 ${c.chapter} 章 · 回忆概念</span><strong>${esc(c.term)}</strong><span>点击翻面查看答案</span></span><span class="fc-back" hidden><span class="fc-meta">参考答案</span><span>${esc(c.answer)}</span><small>点击返回问题</small></span></button><a href="#chapter/${c.chapter}/topic/${c.j}">阅读对应知识点</a></article>`}function bind(){content.querySelectorAll('.fc-flip').forEach(b=>b.onclick=()=>{const front=b.querySelector('.fc-front'),back=b.querySelector('.fc-back'),show=back.hidden;front.hidden=show;back.hidden=!show;b.setAttribute('aria-expanded',String(show));window.renderMath?.()})}function draw(){const p=pool();if(!p.length){status.textContent='此章节暂无卡片';content.innerHTML='';return}let shown=p;if(mode==='random'){let candidates=p.length>1?p.filter(x=>x.term!==previous):p;const c=candidates[Math.floor(Math.random()*candidates.length)];previous=c.term;shown=[c]}status.textContent=mode==='random'?`随机复习 · 当前范围 ${p.length} 张`:`共 ${p.length} 张卡片 · 点击卡片翻面`;content.innerHTML=(mode==='random'?'<div class="fc-random-action"><button id="fc-next" type="button">再抽一张</button></div>':'')+`<div class="fc-grid ${mode==='random'?'single':''}">${shown.map(card).join('')}</div>`;if(mode==='random')document.querySelector('#fc-next').onclick=draw;bind();window.renderMath?.()}select.onchange=()=>{previous=null;draw()};document.querySelector('#fc-browse').onclick=()=>{mode='browse';draw()};document.querySelector('#fc-random').onclick=()=>{mode='random';previous=null;draw()};draw()}
